import{_ as i,o as s,c as t,ag as e}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/image47.png",l="/nada-documentation/images/image48.png",y=JSON.parse('{"title":"Tools for API users","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/api-tools.md","filePath":"admin-guide/api-tools.md","lastUpdated":1786379412000}'),o={name:"admin-guide/api-tools.md"};function p(h,a,r,d,c,g){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="tools-for-api-users" tabindex="-1">Tools for API users <a class="header-anchor" href="#tools-for-api-users" aria-label="Permalink to &quot;Tools for API users&quot;">​</a></h1><p>To facilitate the maintenance of NADA catalogs using the API, a R package (NADAR) and a Python library (PyNADA) have been developed. Both provide a collection of functions that allow catalog administrator to perform many of the catalog maintenance operations via API, often in a more efficient manner than can be done using the administrator interface. Indeed, the programmatic maintenance of a catalog enables the automation and replicability of multiple tasks. The use of the API is therefore highly recommended for organizations that have skills in R and/or Python.</p><p>The NADA API is not only intended to support catalog curators, but also the public who will have access to the catalog. If most API functions are only accessible to catalog administrators, others are publicly accessible.</p><h2 id="r-package-nadar" tabindex="-1">R package NADAR <a class="header-anchor" href="#r-package-nadar" aria-label="Permalink to &quot;R package NADAR&quot;">​</a></h2><p>The NADAR package must be installed from its GitHub repository. It is currently not available on the CRAN. To install NADAR:</p><div class="language-r vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">r</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">library</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(devtools)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">install_github</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mah0001/nadar&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Once installed, NADAR functions and their documentation will be available in R, RStudio, or other IDE.</p><p><img src="`+n+'" alt=""></p><h2 id="python-library-pynada" tabindex="-1">Python library PyNADA <a class="header-anchor" href="#python-library-pynada" aria-label="Permalink to &quot;Python library PyNADA&quot;">​</a></h2><p>The PyNADA package was developed for Python 3.n. It is available on GitHub (<a href="https://github.com/kl9ch/PyNADA" target="_blank" rel="noreferrer">https://github.com/kl9ch/PyNADA</a>) and PyPI (<a href="https://pypi.org/project/pynada/" target="_blank" rel="noreferrer">https://pypi.org/project/pynada/</a>). To install PyNADA:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pip install pynada</span></span></code></pre></div><p><img src="'+l+`" alt=""></p><p>You can also install the latest development version directly from the github repository with:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pip install git</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kl9ch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PyNADA</span></span></code></pre></div><p>or by cloning from the github repository then installing:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kl9ch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PyNADA</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd PyNADA</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pip install PyNADA</span></span></code></pre></div><p>To install from github using the above methods, git needs to be installed on your computer and included in your PATH environment variable. Instructions on how to install git are provided here: <a href="https://github.com/git-guides/install-git" target="_blank" rel="noreferrer">https://github.com/git-guides/install-git</a></p>`,17)])])}const u=i(o,[["render",p]]);export{y as __pageData,u as default};
